/** 로그인 여부 + 내 정보. 401이면 로그아웃 상태 */
me: () => request<MeResponse>('GET', '/api/v1/auth/me'),
/** 실명 최초 등록(FC-013). 400 형식 오류 · 409 `DISPLAY_NAME_ALREADY_SET` */
putDisplayName: (displayName: string) => request<MeResponse>('PUT', '/api/v1/users/me/display-name', { displayName }),

/** 카카오 로그인 시작 주소. 로그인 뒤 돌아올 경로(FC-014 1-2) — `/jungsan/`으로 시작하는 것만 서버가 받는다 */
kakaoLoginUrl: (returnTo?: string) =>
  `${BASE}/api/v1/auth/kakao/login${returnTo ? `?returnTo=${encodeURIComponent(returnTo)}` : ''}`,
/** 로그아웃 — 서버 세션을 끊고 쿠키를 지운다 */

// 정산 단위 — 다음 차 총무(FC-015)
createUnit: (gid: number, requestId: string, participantIds: number[], headcount?: number) =>
  request<{ id: number }>('POST', `/api/v1/gatherings/${gid}/settlement-units`, { requestId, participantIds, headcount }),
/** 인원(FC-020) — 총무·정산 전. 바꾼 뒤 서버가 자동 정산 판정을 한 번 돈다 */

}
export type ServerUnit = {
  id: number; hostParticipantId: number; status: Gathering['status']; inputRevision: number
  /** 총무가 넣은 인원(FC-020). 서버가 아직 안 주면 undefined */

}
export type ServerGathering = {
  id: number; title: string; date: string; createdByUserId: number; shareToken: string
  status: Gathering['status']; completedAt: string | null; deleteScheduledAt: string | null

/** 서버 술자리 하나 → 내가 들어 있는 정산 단위마다 정산방 하나 */
export function toRooms(g: ServerGathering): Gathering[] {
  return g.settlementUnits
    .filter((u) => u.me.included || u.hostParticipantId === g.me.participantId)

// 다음 차 인원의 시작값은 고른 사람 + 나(FC-020) — R2에서 바꿀 수 있다
const u = await api.createUnit(gid, uuid(), ids, ids.length)
await refresh(gid)
return { id: u.id }

  // 다음 차 인원의 시작값은 고른 사람 + 나(FC-020) — R2에서 바꿀 수 있다
  headcount: Math.max(HEADCOUNT_MIN, picked.size),
}
set((s) => ({ rooms: { ...s.rooms, [id]: g, [src.id]: src.gatheringId ? src : { ...src, gatheringId } } }))
